export function getAllBundleItemKeys() {
  const keys = new Set();
  bundleRooms.forEach(room => {
    room.bundles.forEach(bundle => {
      bundle.items.forEach((item, index) => {
        keys.add(`${room.id}:${bundle.id}:${index}`);
      });
    });
  });
  return keys;
}
